new file mode 100644
index 0000000..f53b62b
--- /dev/null
+++ b/src/server.ts
@@ -0,0 +1,36 @@
+import { createServer } from "http";
+import { pool } from "./pool.ts";
+
+const PORT = parseInt(process.env.PORT || "3000", 10);
+
+const server = createServer(async (req, res) => {
+  if (req.method === "POST" && req.url === "/jobs/claim") {
+    try {
+      const result = await pool.query(
+        "SELECT id, payload FROM jobs WHERE status = 'ready' ORDER BY created_at LIMIT 1",
+      );
+      const row = result.rows[0];
+
+      if (row === undefined) {
+        res.writeHead(204); // No Content
+        res.end();
+        return;
+      }
+
+      await pool.query("UPDATE jobs SET status = 'claimed' WHERE id = $1", [row.id]);
+
+      res.writeHead(200, { "Content-Type": "application/json" });
+      res.end(JSON.stringify({ id: row.id, payload: row.payload }));
+    } catch (error) {
+      res.writeHead(500, { "Content-Type": "application/json" });
+      res.end(JSON.stringify({ error: "Internal server error" }));
+    }
+  } else {
+    res.writeHead(404);
+    res.end();
+  }
+});
+
+server.listen(PORT, () => {
+  console.log(`Jobs API listening on port ${PORT}`);
+});
